def topological_sort(nodes, edges):
    def _heap_push(h, value):
        h.append(value)
        i = len(h) - 1
        while i > 0:
            parent = (i - 1) // 2
            if h[parent] <= h[i]:
                break
            h[parent], h[i] = h[i], h[parent]
            i = parent

    def _heap_pop(h):
        last = h.pop()
        if not h:
            return last
        top = h[0]
        h[0] = last
        n = len(h)
        i = 0
        while True:
            left = 2 * i + 1
            right = left + 1
            smallest = i
            if left < n and h[left] < h[smallest]:
                smallest = left
            if right < n and h[right] < h[smallest]:
                smallest = right
            if smallest == i:
                break
            h[i], h[smallest] = h[smallest], h[i]
            i = smallest
        return top

    node_set = set(nodes)
    adjacency = {node: [] for node in nodes}
    in_degree = {node: 0 for node in nodes}

    seen_edges = set()
    for source, destination in edges:
        if source not in node_set:
            raise ValueError("Edge source %r is not present in nodes" % (source,))
        if destination not in node_set:
            raise ValueError("Edge destination %r is not present in nodes" % (destination,))
        edge = (source, destination)
        if edge in seen_edges:
            continue
        seen_edges.add(edge)
        adjacency[source].append(destination)
        in_degree[destination] += 1

    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            _heap_push(heap, node)

